// @name Minesweeper
// @background #f3f1ec
// @refresh 3600
// Minesweeper for a touch screen. Tap a square to open it, switch to Flag to
// mark a mine (or hold a square on a fast screen), and tap an open number
// whose mines are all flagged to open the rest around it. The first square
// opened is never a mine. The game in progress and the best times are kept.
import { newGame, reveal, chord, toggleFlag, numbers, flagCount } from './logic'
import { highContrast, canvasOf, clamp, Button, OptionsPage, Title } from './ui'

const THEMES = {
  color: {
    page: 'bg-[#f3f1ec] text-[#1f2933]',
    muted: 'text-[#5d6873]',
    button: 'bg-[#e3dfd5] text-[#1f2933] active:bg-[#d5cfc1]',
    primary: 'bg-[#34495e] text-white active:bg-[#44607a]',
    on: 'bg-[#34495e] text-white',
    off: 'bg-[#e3dfd5] text-[#1f2933]',
    frame: '#34495e',
    tile: '#6f8799',
    tileEdge: '#5a7183',
    open: '#ebe7de',
    grid: '#d2cbbd',
    numbers: ['', '#2b5f9e', '#2e7d4f', '#b8432f', '#4b3a8c', '#8a3324', '#1f7a7a', '#222222', '#6b6b6b'],
    flag: '#c8553d',
    pole: '#ffffff',
    mine: '#1f2933',
    shine: '#ffffff',
    boom: '#e07a5f',
    wrong: '#ffffff',
    icon: 'text-[#34495e]',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    on: 'bg-black text-white',
    off: 'bg-white text-black border-2 border-black',
    frame: '#000000',
    tile: '#000000',
    tileEdge: '#000000',
    open: '#ffffff',
    grid: '#000000',
    numbers: ['', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000', '#000000'],
    flag: '#ffffff',
    pole: '#ffffff',
    mine: '#000000',
    shine: '#ffffff',
    boom: '#000000',
    wrong: '#ffffff',
    icon: 'text-black',
  },
}

const LEVELS = {
  beginner: { name: 'Beginner', cols: 9, rows: 9, mines: 10 },
  intermediate: { name: 'Intermediate', cols: 16, rows: 16, mines: 40 },
  expert: { name: 'Expert', cols: 0, rows: 0, mines: 0 },
  custom: { name: 'Custom', cols: 0, rows: 0, mines: 0 },
}

const settingsOf = (app) => {
  const level = LEVELS[app.state.difficulty] ? app.state.difficulty : 'beginner'
  const cols = clamp(Math.round(Number(app.state.customColumns) || 12), 5, 30)
  const rows = clamp(Math.round(Number(app.state.customRows) || 10), 5, 24)
  const mines = clamp(Math.round(Number(app.state.customMines) || 20), 1, cols * rows - 9)
  return { level, cols, rows, mines }
}

// What a game was made from: a game whose key no longer matches the settings
// gives way to a new one. Expert's size comes from the screen when it starts,
// so a window of another size keeps the game.
const keyOf = (s) => (s.level === 'custom' ? `custom:${s.cols}x${s.rows}:${s.mines}` : s.level)

// The game in progress, kept in the scene's private `game` field.
type Kept = any
const loadGame = (app): Kept | null => {
  const g = app.state.game
  return g && typeof g.cells === 'string' && g.cols > 0 && g.cells.length === g.cols * g.rows ? g : null
}
const save = (game) => frameos.setState('game', game)

// Expert fills the board's area with squares a finger can still hit, about
// a fifth of them mines (the classic 99 of 480).
const expertSize = (areaW: number, areaH: number, short: number) => {
  const cell = Math.max(30, short / 16)
  const cols = clamp(Math.floor(areaW / cell), 9, 30)
  const rows = clamp(Math.floor(areaH / cell), 9, 24)
  return { cols, rows, mines: Math.round(cols * rows * 0.206) }
}

const formatTime = (ms: number) => {
  const s = Math.max(0, Math.round(ms / 1000))
  return s >= 3600 ? `${Math.floor(s / 3600)}:${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

// A tap on square `i`: open it (or flag it in flag mode); on an open number,
// open its neighbours when its flags are placed.
const tapCell = (app, i: number, flag: boolean) => {
  const game = loadGame(app)
  if (!game || i < 0 || i >= game.cells.length) return
  const now = Date.now()
  if (game.cells[i] === '1') chord(game, i, Math.random, now)
  else if (flag) toggleFlag(game, i)
  else if (game.cells[i] === '0') reveal(game, i, Math.random, now)
  else return
  if (game.state === 'won') recordBest(app, game)
  save(game)
}

const recordBest = (app, game: Kept) => {
  const best = app.state.best && typeof app.state.best === 'object' ? { ...app.state.best } : {}
  const time = game.ended - game.started
  if (!best[game.key] || time < best[game.key]) {
    best[game.key] = time
    frameos.setState('best', best)
    frameos.remember('record', true)
  } else frameos.remember('record', false)
}

const restart = () => {
  save({ cols: 0 })
  frameos.remember('page', null)
  frameos.remember('flag', false)
}

const toggleMode = () => frameos.remember('flag', !frameos.recall('flag'))

// Buttons and keys on frames without a touch screen: forward is a new game,
// back switches between opening and flagging. N and F do the same on a
// keyboard.
export function onEvent(app, context) {
  const event = context.event
  if (event === 'forward') restart()
  else if (event === 'back') toggleMode()
  else if (event === 'keyDown') {
    const p = context.payload || {}
    const key = String(p.key || '').toLowerCase()
    if (p.ctrl || p.alt || p.meta) return false
    if (key === 'n') restart()
    else if (key === 'f') toggleMode()
    else return false
  } else return false
  return true
}

// The pictures inside a square, 100 units across.
const Flag = ({ x, y, t }) => (
  <g>
    <line x1={x + 38} y1={y + 22} x2={x + 38} y2={y + 76} stroke={t.pole} strokeWidth={7} strokeLinecap="round" />
    <polygon points={`${x + 41},${y + 20} ${x + 76},${y + 36} ${x + 41},${y + 52}`} fill={t.flag} />
    <rect x={x + 24} y={y + 72} width={30} height={8} rx={3} fill={t.pole} />
  </g>
)
const Mine = ({ x, y, fill, shine }) => (
  <g>
    <line x1={x + 50} y1={y + 16} x2={x + 50} y2={y + 84} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 16} y1={y + 50} x2={x + 84} y2={y + 50} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 26} y1={y + 26} x2={x + 74} y2={y + 74} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <line x1={x + 74} y1={y + 26} x2={x + 26} y2={y + 74} stroke={fill} strokeWidth={8} strokeLinecap="round" />
    <circle cx={x + 50} cy={y + 50} r={24} fill={fill} />
    <circle cx={x + 42} cy={y + 42} r={7} fill={shine} />
  </g>
)

const Board = ({ t, game, high, width, height }) => {
  const { cols, rows } = game
  const nums = numbers(game)
  const over = game.state === 'lost'
  const parts = []
  for (let c = 1; c < cols; c++) parts.push(<line x1={c * 100} y1={0} x2={c * 100} y2={rows * 100} stroke={t.grid} strokeWidth={high ? 3 : 4} />)
  for (let r = 1; r < rows; r++) parts.push(<line x1={0} y1={r * 100} x2={cols * 100} y2={r * 100} stroke={t.grid} strokeWidth={high ? 3 : 4} />)
  for (let i = 0; i < game.cells.length; i++) {
    const x = (i % cols) * 100
    const y = Math.floor(i / cols) * 100
    const cell = game.cells[i]
    const mine = game.layout[i] === '1'
    if (cell === '1') {
      if (i === game.boom) {
        parts.push(<rect x={x} y={y} width={100} height={100} fill={t.boom} />)
        parts.push(<Mine x={x} y={y} fill={high ? '#ffffff' : t.mine} shine={high ? '#000000' : t.shine} />)
      } else if (nums[i]) {
        parts.push(
          <text x={x + 50} y={y + 73} fontSize={64} fontWeight="bold" textAnchor="middle" fill={t.numbers[nums[i]]}>
            {String(nums[i])}
          </text>,
        )
      }
      continue
    }
    // A lost game shows every mine, and crosses out the flags that were wrong.
    if (over && mine && cell === '0') {
      parts.push(<Mine x={x} y={y} fill={t.mine} shine={t.shine} />)
      continue
    }
    parts.push(<rect x={x + 5} y={y + 5} width={90} height={90} rx={12} fill={t.tile} stroke={t.tileEdge} strokeWidth={3} />)
    if (cell === '2') {
      parts.push(<Flag x={x} y={y} t={t} />)
      if (over && !mine) {
        parts.push(<line x1={x + 18} y1={y + 18} x2={x + 82} y2={y + 82} stroke={t.wrong} strokeWidth={9} strokeLinecap="round" />)
        parts.push(<line x1={x + 82} y1={y + 18} x2={x + 18} y2={y + 82} stroke={t.wrong} strokeWidth={9} strokeLinecap="round" />)
      }
    }
  }
  return (
    <svg viewBox={`-8 -8 ${cols * 100 + 16} ${rows * 100 + 16}`} width={width} height={height}>
      <rect x={-6} y={-6} width={cols * 100 + 12} height={rows * 100 + 12} rx={10} fill={t.frame} />
      <rect x={0} y={0} width={cols * 100} height={rows * 100} fill={t.open} />
      {parts}
    </svg>
  )
}

const MineIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <line x1={12} y1={2} x2={12} y2={22} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={2} y1={12} x2={22} y2={12} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={5} y1={5} x2={19} y2={19} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <line x1={19} y1={5} x2={5} y2={19} stroke="currentColor" strokeWidth={2.4} strokeLinecap="round" />
    <circle cx={12} cy={12} r={7} fill="currentColor" />
  </svg>
)
const FlagIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <path d="M6 2h2v18h3v2H3v-2h3zM9 3l10 4.5L9 12z" fill="currentColor" />
  </svg>
)

// The options button where there is no room for its word.
const SlidersIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className}>
    <line x1={3} y1={6} x2={21} y2={6} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={12} x2={21} y2={12} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <line x1={3} y1={18} x2={21} y2={18} stroke="currentColor" strokeWidth={2} strokeLinecap="round" />
    <circle cx={8} cy={6} r={2.6} fill="currentColor" />
    <circle cx={16} cy={12} r={2.6} fill="currentColor" />
    <circle cx={10} cy={18} r={2.6} fill="currentColor" />
  </svg>
)

export function get(app, context) {
  const ui = canvasOf(app, context)
  const high = highContrast(app)
  const t = high ? THEMES.high : THEMES.color
  const settings = settingsOf(app)

  if (frameos.recall('page') === 'options') {
    const rows: any[] = [
      { field: 'difficulty', label: 'Difficulty', value: settings.level,
        options: [['beginner', 'Beginner'], ['intermediate', 'Intermediate'], ['expert', 'Expert'], ['custom', 'Custom']] },
    ]
    if (settings.level === 'custom') {
      rows.push({ field: 'customColumns', label: 'Columns', value: settings.cols, min: 5, max: 30 })
      rows.push({ field: 'customRows', label: 'Rows', value: settings.rows, min: 5, max: 24 })
      rows.push({ field: 'customMines', label: 'Mines', value: settings.mines, min: 1, max: settings.cols * settings.rows - 9, step: 5 })
    }
    return <OptionsPage ui={ui} t={t} title="Minesweeper" rows={rows}
      onClose={() => frameos.remember('page', null)} onNew={restart} />
  }

  // Side by side on a wide screen; on a tall one a bar above the board and
  // one below; on a square one everything in the bar below.
  const side = ui.W >= ui.H * 1.15
  const tall = !side && ui.H > ui.W * 1.25
  const sideW = Math.round(Math.max(ui.W * 0.26, ui.text * 9))
  const areaW = side ? ui.W - sideW - ui.pad * 3 : ui.W - ui.pad * 2
  const areaH = side ? ui.H - ui.pad * 2 : ui.H - ui.pad * 2 - (ui.gap + ui.button) * (tall ? 2 : 1)

  // A new game when there is none or the settings changed.
  const key = keyOf(settings)
  let game = loadGame(app)
  if (!game || game.key !== key) {
    const size = settings.level === 'custom' ? settings
      : settings.level === 'expert' ? expertSize(areaW, areaH, Math.min(ui.W, ui.H))
      : LEVELS[settings.level]
    game = { ...newGame(size.cols, size.rows, size.mines), key }
    save(game)
    frameos.remember('flag', false)
  }

  const flagMode = !!frameos.recall('flag')
  const cell = Math.floor(Math.min(areaW / (game.cols + 0.16), areaH / (game.rows + 0.16)))
  const boardW = Math.round(cell * (game.cols + 0.16))
  const boardH = Math.round(cell * (game.rows + 0.16))
  const at = (e) => {
    const col = Math.floor(((e.localX / e.width) * (game.cols * 100 + 16) - 8) / 100)
    const row = Math.floor(((e.localY / e.height) * (game.rows * 100 + 16) - 8) / 100)
    return col >= 0 && col < game.cols && row >= 0 && row < game.rows ? row * game.cols + col : -1
  }
  const board = (
    <div className={`w-[${boardW}px] h-[${boardH}px] shrink-0`}
      onClick={(e) => tapCell(app, at(e), flagMode)}
      onLongPress={(e) => tapCell(app, at(e), !flagMode)}>
      <Board t={t} game={game} high={high} width={boardW} height={boardH} />
    </div>
  )

  const best = app.state.best && typeof app.state.best === 'object' ? app.state.best[game.key] : 0
  const left = game.mines - flagCount(game)
  const levelName = `${LEVELS[settings.level].name} · ${game.cols}×${game.rows}`
  let headline = ''
  let detail = ''
  if (game.state === 'won') {
    headline = 'Cleared!'
    detail = `${formatTime(game.ended - game.started)}${frameos.recall('record') ? ', a new best' : best ? ` (best ${formatTime(best)})` : ''}`
  } else if (game.state === 'lost') {
    headline = 'Boom!'
    detail = 'That one was a mine.'
  } else if (game.state === 'ready') {
    detail = 'Tap any square to start'
  } else if (flagMode) {
    detail = 'Taps place flags'
  }

  const iconSize = Math.round(ui.big * 1.1)
  const counter = (
    <div className={`flex items-center gap-[${Math.round(ui.gap * 0.6)}px]`}>
      <MineIcon className={`w-[${iconSize}px] h-[${iconSize}px] ${t.icon}`} />
      <span className={`text-[${Math.round(ui.big * 1.15)}px] font-bold`}>{String(left)}</span>
    </div>
  )
  const result = (
    <div className="flex flex-col">
      {headline ? <span className={`text-[${ui.big}px] font-bold leading-tight`}>{headline}</span> : null}
      {detail ? <span className={`text-[${ui.small}px] ${t.muted}`}>{detail}</span> : null}
    </div>
  )
  const modeIcon = Math.round(ui.text * 1.1)
  const modeButtons = [
    <Button ui={ui} grow className={flagMode ? t.off : t.on} onClick={() => frameos.remember('flag', false)}>
      Open
    </Button>,
    <Button ui={ui} grow className={flagMode ? t.on : t.off} onClick={() => frameos.remember('flag', true)}>
      <div className="flex items-center gap-[6px]">
        <FlagIcon className={`w-[${modeIcon}px] h-[${modeIcon}px]`} />
        <span>Flag</span>
      </div>
    </Button>,
  ]
  const over = game.state === 'won' || game.state === 'lost'
  const newButton = <Button ui={ui} grow className={over ? t.primary : t.button} onClick={restart}>New</Button>
  const openOptions = () => frameos.remember('page', 'options')
  const gap = Math.round(ui.gap * 0.6)

  if (side) {
    return (
      <div className={`flex w-full h-full p-[${ui.pad}px] gap-[${ui.pad}px] items-center ${t.page}`}>
        <div className="flex-1 h-full flex items-center justify-center">{board}</div>
        <div className={`w-[${sideW}px] h-full flex flex-col gap-[${ui.gap}px]`}>
          <Title ui={ui} width={sideW}>Minesweeper</Title>
          <span className={`text-[${ui.small}px] ${t.muted}`}>{levelName}</span>
          {counter}
          {result}
          <div className="flex-1" />
          <div className={`flex gap-[${gap}px]`}>{modeButtons}</div>
          <div className={`flex gap-[${gap}px]`}>
            {newButton}
            <Button ui={ui} grow className={t.button} onClick={openOptions}>Options</Button>
          </div>
        </div>
      </div>
    )
  }
  if (tall) {
    return (
      <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
        <div className={`flex items-center gap-[${ui.gap * 2}px] h-[${ui.button}px]`}>
          {counter}
          <div className="flex-1 min-w-0">{headline || detail ? result : <span className={`text-[${ui.small}px] ${t.muted}`}>{levelName}</span>}</div>
        </div>
        <div className="flex-1 flex items-center justify-center">{board}</div>
        <div className={`flex gap-[${gap}px]`}>
          {modeButtons}
          {newButton}
          <Button ui={ui} grow className={t.button} onClick={openOptions}>Options</Button>
        </div>
      </div>
    )
  }
  // Square: the counter, then the result once the game is over (else the
  // Open / Flag pair), a new game and the options as an icon.
  const sliders = Math.round(ui.text * 1.3)
  return (
    <div className={`flex flex-col w-full h-full p-[${ui.pad}px] gap-[${ui.gap}px] ${t.page}`}>
      <div className="flex-1 flex items-center justify-center">{board}</div>
      <div className={`flex items-center gap-[${gap}px]`}>
        <div className={`pr-[${gap}px]`}>{counter}</div>
        {over ? <div className="flex-1 min-w-0">{result}</div> : modeButtons}
        {newButton}
        <Button ui={ui} className={`w-[${ui.button}px] ${t.button}`} onClick={openOptions}>
          <SlidersIcon className={`w-[${sliders}px] h-[${sliders}px]`} />
        </Button>
      </div>
    </div>
  )
}

